// Generated by vibelang from src/state/threadCheckpoints.vibe; the migrate flow writes it again with each batch.
import * as DateTime from "effect/DateTime";
export function deriveThreadCheckpointSummaries(projection) {
    return projection.checkpoints.flatMap((checkpoint) => {
        if (checkpoint.appRunOrdinal === null || checkpoint.runId === null)
            return [];
        const assistantMessageId = projection.messages.findLast((message) => message.runId === checkpoint.runId && message.role === "assistant")?.id ?? null;
        return [
            {
                checkpointId: checkpoint.id,
                scopeId: checkpoint.scopeId,
                runId: checkpoint.runId,
                checkpointTurnCount: checkpoint.appRunOrdinal,
                checkpointRef: checkpoint.ref,
                status: checkpoint.status,
                files: checkpoint.files,
                assistantMessageId,
                completedAt: DateTime.formatIso(checkpoint.capturedAt),
            },
        ];
    });
}
